document.querySelectorAll('[data-interval]').forEach(b=>b.addEventListener('click',()=>{const annual=b.dataset.interval==='annual';document.querySelectorAll('[data-interval]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('#pro-price').textContent=annual?'$60':'$5';document.querySelector('#pro-unit').textContent=annual?'/ year':'/ month';document.querySelector('#pro-billing').textContent=annual?'Planned: $60 billed annually. Equivalent to $5/month.':'Planned: $5 billed monthly.';}));